import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a,a as o,b as s,c as n,d as t,e as l}from"./chunks/Companion6.vBiva1QN.js";import{_ as r,o as p,c,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const q=JSON.parse('{"title":"Application compagnon","description":"","frontmatter":{"source_hash":"70c4ce8344","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/install/companion.md","filePath":"fr/install/companion.md"}'),u={name:"fr/install/companion.md"};function m(f,i,_,h,v,g){return p(),c("div",null,[...i[0]||(i[0]=[d('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle<br>   Companion App</p></div><p>Si vous utilisez l&#39;application du fabricant, xDrip peut récupérer les données du capteur depuis celle-ci.</p><p>Cette fonction est disponible pour :</p><ul><li>les applications G6/G7 (principal uniquement)</li><li>les applications ONE/ONE+ et Stelo (uniquement si l&#39;application affiche des notifications de glycémie)</li><li>l&#39;application CamAPS (y compris la version canadienne)</li><li>les applications Guardian, MiniMed, Simplera</li><li>les applications Eversense</li><li>les applications Micro tech Aidex, LinX Vista, Equil G</li><li>les applications Micro tech Diaexpert (Allemagne) et Smart 2 (Brésil)</li><li>l&#39;application GlucoRx Vixxa (Inde)</li><li>les applications Ottai Sens et Tag</li><li>l&#39;application Pasta</li><li>les applications CareSens et iCan (Sinocare)</li><li>l&#39;application Vitatok</li><li>l&#39;application Glucotech</li><li>l&#39;application SiSensing Eco (Chine)</li><li>l&#39;application Diabeloop DBLG2</li></ul><p>Pour les applications Omnipod 5 et MiniMed Mobile (EU), xDrip lit aussi l&#39;insuline active (IoB) dans la notification de l&#39;application compagnon lorsqu&#39;elle est disponible. Pour MiniMed Mobile (EU), cela fonctionne quelle que soit la langue de l&#39;application.</p><p>Pour utiliser cette fonction, vous <strong>devez</strong> autoriser xDrip à accéder aux notifications.</p><p>xDrip n&#39;utilisera cet accès à aucune autre fin que la lecture de la valeur de glycémie dans les notifications.</p><div class="admonition xdripitem"><p class="admonition-title">Veuillez autoriser les permissions</p><p>Une autorisation est nécessaire pour recevoir les données d&#39;autres applications. xDrip ne fait rien d&#39;autre que recevoir. Veuillez activer xDrip sur l&#39;écran suivant</p><p>     <span style="background-color:white;color:black;"> OK </span></p></div><h4 id="older-android-versions" tabindex="-1">Anciennes versions d&#39;Android <a class="header-anchor" href="#older-android-versions" aria-label="Permalink to &quot;Anciennes versions d&#39;Android {#older-android-versions}&quot;">​</a></h4><img src="'+a+'" style="zoom:78%;"><h4 id="android-13-and-above" tabindex="-1">Android 13 et versions ultérieures <a class="header-anchor" href="#android-13-and-above" aria-label="Permalink to &quot;Android 13 et versions ultérieures {#android-13-and-above}&quot;">​</a></h4><img src="'+o+'" style="zoom:78%;"><img src="'+s+'" style="zoom:78%;"><img src="'+n+'" style="zoom:78%;"><h4 id="allow-notification-access-greyed-out" tabindex="-1">Autoriser l&#39;accès aux notifications grisé <a class="header-anchor" href="#allow-notification-access-greyed-out" aria-label="Permalink to &quot;Autoriser l&#39;accès aux notifications grisé {#allow-notification-access-greyed-out}&quot;">​</a></h4><img src="'+t+'" style="zoom:78%;"><p>Si vous ne pouvez pas autoriser l&#39;accès aux notifications, ouvrez le menu à trois points dans les paramètres de l&#39;application et choisissez Autoriser les paramètres restreints.</p><img src="'+l+'" style="zoom:78%;"><br><p>Vous recevrez des données dans xDrip lorsqu&#39;elles sont disponibles dans l&#39;application et que les notifications de l&#39;application sont visibles sur le téléphone.</p><p>Si aucune donnée n&#39;apparaît et qu&#39;aucun message d&#39;erreur ne s&#39;affiche, vous devrez peut-être <a href="./../use/startsensor.html#followers-and-companion-apps">Démarrer le capteur</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.20" target="_blank" rel="noreferrer"><em>Dernière modification le 22/11/2026</em></a></p>',23)])])}const A=r(u,[["render",m]]);export{q as __pageData,A as default};
